package game.agent.eval;

import game.agent.llm.Json;
import game.agent.persistence.WorldStore;
import java.util.*;
import java.util.concurrent.Executor;

/** Owner-scoped bounded queue; each case has its own atomic checkpoint document. */
public final class EvaluationService implements AutoCloseable {
 private final String owner;private final WorldStore store;private final EvaluationProviders providers;private final Executor executor;
 private final LinkedHashMap<String,Map<String,Object>> batches=new LinkedHashMap<>(),receipts=new LinkedHashMap<>();
 private final Map<String,Map<String,Object>> volatileRuns=new HashMap<>();private final Map<String,Map<String,Object>> volatileUsage=new java.util.concurrent.ConcurrentHashMap<>();private final Object ledgerLock=new Object();
 private final LinkedHashSet<String> pendingPurge=new LinkedHashSet<>();
 private final int archiveMaximum=Math.max(1,Math.min(64,Integer.getInteger("pokemon.eval.archiveMaximum",30)));private final long archiveMillis=Math.max(1,Math.min(365,Long.getLong("pokemon.eval.archiveDays",30L)))*86400000L;
 private String paidDay="";private long paidCases;
 private EvaluationRun active;private String activeBatch;private long revision;private boolean storageError;
 public EvaluationService(String owner,WorldStore store,EvaluationProviders providers,Executor executor){this.owner="evaluation:"+Objects.requireNonNull(owner);this.store=store;this.providers=providers;this.executor=executor;load();}
 private void load(){Map<String,Object> saved=store==null?null:store.load(owner);if(saved==null)return;if(EvaluationRandom.number(saved.get("schemaVersion"))!=1)throw new IllegalArgumentException("INVALID_EVALUATION_INDEX");revision=EvaluationRandom.number(saved.get("revision"));if(saved.containsKey("purgeJson"))for(Object id:Json.asArray(Json.read((String)saved.get("purgeJson")))){if(!(id instanceof String)||!((String)id).matches("[a-f0-9-]{36}")||pendingPurge.size()>=1024)throw new IllegalArgumentException("INVALID_PURGE_INDEX");pendingPurge.add((String)id);}if(saved.containsKey("paidQuota")){Map<String,Object> quota=Json.asObject(saved.get("paidQuota"));paidDay=(String)quota.get("day");paidCases=EvaluationRandom.number(quota.get("cases"));if(paidDay==null||paidCases<0||paidCases>6)throw new IllegalArgumentException("INVALID_PAID_QUOTA");}for(Object v:Json.asArray(saved.containsKey("batchesJson")?Json.read((String)saved.get("batchesJson")):saved.get("batches"))){Map<String,Object> batch=Json.asObject(v);String id=(String)batch.get("id");if(batches.size()>=72||!id.matches("[a-f0-9-]{36}"))throw new IllegalArgumentException("INVALID_EVALUATION_INDEX");if(Arrays.asList("RUNNING","QUEUED").contains(batch.get("status")))batch.put("status","PAUSED");batches.put(id,batch);for(Object item:Json.asArray(batch.get("cases"))){Map<String,Object> row=Json.asObject(item);EvaluationRun run=restoreRun((String)row.get("id"));row.putAll(run.report(false));}if(!"CANCELLED".equals(batch.get("status")))finish(batch);}for(Object v:Json.asArray(saved.containsKey("receiptsJson")?Json.read((String)saved.get("receiptsJson")):saved.get("receipts"))){Map<String,Object> receipt=Json.asObject(v);receipts.put((String)receipt.get("id"),receipt);}}
 public Map<String,Object> catalog(){return Json.object("publicPaidLimits",providers.publicPaidLimits(),"models",providers.models(),"scenarios",EvaluationRun.SCENARIOS,"maxCases",24,"maxBatches",8,"archiveMaximum",archiveMaximum,"archiveDays",archiveMillis/86400000L,"rulesVersion","v4-demo-20261003","promptVersion","v4-evaluation-v1","priceUnit","USD per million tokens","checkpointPolicy","Restart pauses unfinished batches; resume continues committed world and RNG cursors. In-flight calls are discarded and may have unknown billed usage.");}
 public Map<String,Object> snapshot(){for(Map<String,Object> batch:batches.values())refreshUsage(batch);return Json.object("publicPaidRemaining",providers.publicPaidLimits().isEmpty()?null:6-(java.time.LocalDate.now(java.time.ZoneId.of("Australia/Sydney")).toString().equals(paidDay)?paidCases:0),"revision",revision,"status",storageError?"STORAGE_ERROR":"READY","batches",new ArrayList<>(batches.values()));}
 public Map<String,Object> command(Map<String,Object> body){if(!body.keySet().equals(new HashSet<>(Arrays.asList("requestId","expectedRevision","command","params"))))throw new IllegalArgumentException("INVALID_FIELDS");String request=(String)body.get("requestId");if(request==null||!request.matches("[a-f0-9-]{36}"))throw new IllegalArgumentException("INVALID_REQUEST_ID");String digest=SeededGrowthFixture.fingerprint(body);Map<String,Object> old=receipts.get(request);if(old!=null){if(!digest.equals(old.get("digest")))throw new IllegalStateException("REQUEST_ID_CONFLICT");return snapshot();}String command=(String)body.get("command");long expected=EvaluationRandom.number(body.get("expectedRevision"));
  // Background case commits change the global revision every step. Batch controls
  // target an immutable batch ID and validate its current state below; they do
  // not replace world data. Keep strict revisions for creation and recovery.
  boolean batchControl=Arrays.asList("PAUSE","RESUME","CANCEL","ARCHIVE","DELETE").contains(command);
  if(expected<0||expected>revision||(!batchControl&&expected!=revision))throw new IllegalStateException("STALE_REVISION");Map<String,Object> params=Json.asObject(body.get("params"));if(storageError&&!"RECOVER".equals(command))throw new IllegalStateException("STORAGE_ERROR");
  try{if("CREATE".equals(command))create(params);else if("RECOVER".equals(command)){if(!params.isEmpty())throw new IllegalArgumentException("INVALID_PARAMS");if(active!=null)active.cancel();active=null;activeBatch=null;batches.clear();receipts.clear();pendingPurge.clear();load();storageError=false;}else{if(!params.keySet().equals(Collections.singleton("batchId")))throw new IllegalArgumentException("INVALID_PARAMS");Map<String,Object> batch=batches.get(params.get("batchId"));if(batch==null)throw new NoSuchElementException("BATCH_NOT_FOUND");String state=(String)batch.get("status");if("PAUSE".equals(command)){if(!Arrays.asList("RUNNING","QUEUED").contains(state))throw new IllegalStateException("BATCH_NOT_RUNNING");if(batch.get("id").equals(activeBatch)){active.pause();saveRun(active);active=null;activeBatch=null;}batch.put("status","PAUSED");}
   else if("RESUME".equals(command)){if(!"PAUSED".equals(state))throw new IllegalStateException("BATCH_NOT_PAUSED");batch.put("status","QUEUED");}
   else if("CANCEL".equals(command)){if(!Arrays.asList("RUNNING","QUEUED","PAUSED").contains(state))throw new IllegalStateException("BATCH_TERMINAL");if(batch.get("id").equals(activeBatch)){active.cancel();saveRun(active);active=null;activeBatch=null;}for(Object v:Json.asArray(batch.get("cases"))){Map<String,Object> row=Json.asObject(v);EvaluationRun run=restoreRun((String)row.get("id"));if(!run.terminal()){run.cancel();saveRun(run);row.putAll(run.report(false));}}batch.put("status","CANCELLED");}
   else if("ARCHIVE".equals(command)||"DELETE".equals(command)){
    if(!terminalBatch(batch))throw new IllegalStateException("BATCH_NOT_TERMINAL");
    if(pendingPurge.size()+rows(batch).size()>1024)throw new IllegalStateException("HISTORY_SETTLEMENT_LIMIT");
    if("ARCHIVE".equals(command)){batch.put("archived",true);if(!batch.containsKey("archivedAt"))batch.put("archivedAt",System.currentTimeMillis());trimArchives();}
    else removeHistory(batch);
   }
   else throw new IllegalArgumentException("UNKNOWN_COMMAND");}
   revision++;receipts.put(request,Json.object("id",request,"digest",digest));while(receipts.size()>64)receipts.remove(receipts.keySet().iterator().next());saveIndex();purgeHistory();return snapshot();
  }catch(game.agent.persistence.StoreException e){freeze();throw new IllegalStateException("STORAGE_ERROR");}
 }
 private void create(Map<String,Object> params){Set<String> fields=new HashSet<>(params.keySet());fields.remove("paidConfirmed");if(!fields.equals(new HashSet<>(Arrays.asList("models","scenarios","seeds","repetitions","starter","decisions","wallMillis","prices"))))throw new IllegalArgumentException("INVALID_PARAMS");if(batches.values().stream().filter(b->!Boolean.TRUE.equals(b.get("archived"))).count()>=8)throw new IllegalStateException("BATCH_LIMIT");List<Object> models=Json.asArray(params.get("models")),scenarios=Json.asArray(params.get("scenarios")),seeds=Json.asArray(params.get("seeds"));int repetitions=(int)bounded(params,"repetitions",1,5);long decisions=bounded(params,"decisions",1,100),wall=bounded(params,"wallMillis",1000,600000);if(models.isEmpty()||scenarios.isEmpty()||seeds.isEmpty()||models.size()>4||scenarios.size()>6||seeds.size()>10||models.size()*scenarios.size()*seeds.size()*repetitions>24||new HashSet<>(models).size()!=models.size()||new HashSet<>(scenarios).size()!=scenarios.size()||new HashSet<>(seeds).size()!=seeds.size())throw new IllegalArgumentException("INVALID_CASE_COUNT");for(Object model:models)if(!providers.models().contains(model))throw new IllegalArgumentException("MODEL_NOT_CONFIGURED");for(Object scenario:scenarios)if(!EvaluationRun.SCENARIOS.contains(scenario))throw new IllegalArgumentException("UNKNOWN_SCENARIO");Set<Long> distinct=new HashSet<>();for(Object seed:seeds)if(!distinct.add(EvaluationRandom.number(seed)))throw new IllegalArgumentException("DUPLICATE_SEED");String starter=(String)params.get("starter");if(!game.agent.growth.GrowthRules.starter(starter))throw new IllegalArgumentException("INVALID_STARTER");Map<String,Object> prices=Json.asObject(params.get("prices"));for(String key:prices.keySet())if(!models.contains(key))throw new IllegalArgumentException("PRICE_MODEL_NOT_SELECTED");Map<String,Map<String,Object>> validated=new HashMap<>();for(Object model:models)validated.put((String)model,EvaluationPricing.validate(prices.get(model)));
  long paidCount=models.stream().filter(m->!"baseline".equals(m)).count()*scenarios.size()*seeds.size()*repetitions;
  String today=java.time.LocalDate.now(java.time.ZoneId.of("Australia/Sydney")).toString();
  if(!providers.publicPaidLimits().isEmpty()&&paidCount>0){
   if(!Boolean.TRUE.equals(params.get("paidConfirmed")))throw new IllegalStateException("PAID_CONFIRMATION_REQUIRED");
   if(paidCount>3||decisions>30||wall>180000)throw new IllegalStateException("PUBLIC_EVAL_LIMIT");
   if((today.equals(paidDay)?paidCases:0)+paidCount>6)throw new IllegalStateException("PUBLIC_EVAL_DAILY_LIMIT");
  }
  String id=UUID.randomUUID().toString();List<Object> cases=new ArrayList<>();
  // Case ordering rotates model order per repetition to reduce a fixed first-model warm-cache bias.
  for(int rep=0;rep<repetitions;rep++)for(Object scenario:scenarios)for(Object seed:seeds)for(int offset=0;offset<models.size();offset++){String model=(String)models.get((offset+rep)%models.size());Map<String,Object> spec=Json.object("id",UUID.randomUUID().toString(),"scenario",scenario,"seed",EvaluationRandom.number(seed),"repetition",rep+1,"model",model,"starter",starter,"decisions",decisions,"wallMillis",wall,"price",validated.get(model));EvaluationRun run=new EvaluationRun(spec);saveRun(run);Map<String,Object> row=run.report(false);row.put("status","QUEUED");cases.add(row);}
  if(!providers.publicPaidLimits().isEmpty()&&paidCount>0){if(!today.equals(paidDay)){paidDay=today;paidCases=0;}paidCases+=paidCount;}
  batches.put(id,Json.object("id",id,"createdAt",System.currentTimeMillis(),"status","QUEUED","configuration",params,"cases",cases));
 }
 public void tick(long now){if(storageError)return;try{if(trimArchives()){revision++;saveIndex();}purgeHistory();
  if(active==null){for(Map<String,Object> batch:batches.values())if(Arrays.asList("QUEUED","RUNNING").contains(batch.get("status"))){for(Object v:Json.asArray(batch.get("cases"))){Map<String,Object> row=Json.asObject(v);if(Arrays.asList("PAUSED","QUEUED","RUNNING").contains(row.get("status"))){active=restoreRun((String)row.get("id"));activeBatch=(String)batch.get("id");final String caseId=active.id();active.usageJournal(ledger->saveUsage(caseId,ledger));try{active.resume(providers.create((String)row.get("model")),executor,providers.timeout());}catch(game.agent.llm.ProviderException e){active.fail();}batch.put("status","RUNNING");saveRun(active);revision++;saveIndex();break;}}if(active!=null)break;finish(batch);}}
  if(active!=null&&(active.terminal()||active.tick(now))){if(active.terminal())active.applyUsageJournal(loadUsage(active.id()));saveRun(active);Map<String,Object> batch=batches.get(activeBatch);for(Object v:Json.asArray(batch.get("cases")))if(active.id().equals(Json.asObject(v).get("id")))Json.asObject(v).putAll(active.report(false));revision++;if(active.terminal()){active=null;activeBatch=null;finish(batch);}saveIndex();}
 }catch(RuntimeException error){System.err.println("Evaluation stopped: "+error.getClass().getSimpleName()+" at "+(error.getStackTrace().length==0?"unknown":error.getStackTrace()[0]));freeze();}}
 private boolean terminalBatch(Map<String,Object> batch){return Arrays.asList("COMPLETED","COMPLETED_WITH_FAILURES","CANCELLED").contains(batch.get("status"));}
 private void removeHistory(Map<String,Object> batch){for(Map<String,Object> row:rows(batch))pendingPurge.add((String)row.get("id"));batches.remove(batch.get("id"));}
 private boolean trimArchives(){
  List<Map<String,Object>> archived=new ArrayList<>();for(Map<String,Object> b:batches.values())if(Boolean.TRUE.equals(b.get("archived"))&&terminalBatch(b))archived.add(b);
  archived.sort(Comparator.comparingLong(b->EvaluationRandom.number(b.get("archivedAt"))));boolean changed=false;long cutoff=System.currentTimeMillis()-Math.max(1,archiveMillis);int left=archived.size();
  for(Map<String,Object> b:archived)if(left>Math.max(1,archiveMaximum)||EvaluationRandom.number(b.get("archivedAt"))<cutoff){if(pendingPurge.size()+rows(b).size()>1024)break;removeHistory(b);left--;changed=true;}return changed;
 }
 /** Index deletion is committed first; large worlds can be purged while unknown fee journals remain. */
 private void purgeHistory(){if(pendingPurge.isEmpty())return;boolean changed=false;synchronized(ledgerLock){for(String id:new ArrayList<>(pendingPurge)){
   boolean removed;if(store==null){volatileRuns.remove(id);removed=true;}else removed=store.delete(runKey(id));if(!removed)continue;
   Map<String,Object> usage=loadUsage(id);boolean outstanding=usage!=null&&EvaluationRandom.number(usage.get("issued"))>Json.asArray(usage.get("calls")).size();
   boolean unknownFee=usage!=null&&!Boolean.FALSE.equals(usage.get("billable"))&&Json.asArray(usage.get("calls")).stream().anyMatch(call->!Json.asObject(Json.asObject(call).get("usage")).containsKey("totalTokens"));if(outstanding||unknownFee)continue;
   if(store==null)volatileUsage.remove(id);else if(!store.delete(runKey(id)+":usage"))continue;
   pendingPurge.remove(id);changed=true;
  }}if(changed)saveIndex();
 }
 private void finish(Map<String,Object> batch){boolean pending=false,passed=true;for(Object v:Json.asArray(batch.get("cases"))){Map<String,Object> row=Json.asObject(v);if(Arrays.asList("PAUSED","QUEUED","RUNNING").contains(row.get("status")))pending=true;if(!"COMPLETED".equals(row.get("status")))passed=false;}if(!pending){batch.put("status",passed?"COMPLETED":"COMPLETED_WITH_FAILURES");batch.put("comparison",EvaluationStatistics.compare(rows(batch)));}}
 public Map<String,Object> report(String batchId){Map<String,Object> batch=batches.get(batchId);if(batch==null)throw new NoSuchElementException("BATCH_NOT_FOUND");refreshUsage(batch);Map<String,Object> out=new LinkedHashMap<>(batch);out.put("comparison",EvaluationStatistics.compare(rows(batch)));out.put("rulesVersion","v4-demo-20261003");out.put("promptVersion","v4-evaluation-v1");out.put("fairness","Matched seed, starter, scenario, repetition, budgets and versions. Model decisions may differ; latency and caching depend on service conditions. Wilson intervals use finished cases only.");return out;}
 public Map<String,Object> replay(String batchId,String runId){Map<String,Object> batch=batches.get(batchId);if(batch==null)throw new NoSuchElementException("BATCH_NOT_FOUND");boolean found=false;for(Map<String,Object> row:rows(batch))if(runId.equals(row.get("id")))found=true;if(!found)throw new NoSuchElementException("RUN_NOT_FOUND");return active!=null&&active.id().equals(runId)?active.report(true):restoreRun(runId).report(true);}
 private void refreshUsage(Map<String,Object> batch){if(storageError)return;for(Map<String,Object> row:rows(batch)){if(Arrays.asList("RUNNING","PAUSED","QUEUED").contains(row.get("status")))continue;String id=(String)row.get("id");Map<String,Object> journal=loadUsage(id);if(journal==null)continue;Map<String,Object> metrics=Json.asObject(row.get("metrics"));if(EvaluationRandom.number(journal.get("issued"))==EvaluationRandom.number(metrics.get("providerCallsIssued"))&&Json.asArray(journal.get("calls")).size()==EvaluationRandom.number(metrics.get("providerCalls")))continue;EvaluationRun run=restoreRun(id);row.put("metrics",run.report(false).get("metrics"));}if(batch.containsKey("comparison"))batch.put("comparison",EvaluationStatistics.compare(rows(batch)));}
 private List<Map<String,Object>> rows(Map<String,Object> batch){List<Map<String,Object>> out=new ArrayList<>();for(Object v:Json.asArray(batch.get("cases")))out.add(Json.asObject(v));return out;}
 private EvaluationRun restoreRun(String id){EvaluationRun run=EvaluationRun.restore(loadRun(id));run.applyUsageJournal(loadUsage(id));return run;}
 private Map<String,Object> loadUsage(String id){return store==null?volatileUsage.get(id):store.load(runKey(id)+":usage");}
 private void saveUsage(String id,Map<String,Object> ledger){synchronized(ledgerLock){Map<String,Object> old=loadUsage(id);TreeMap<Long,Map<String,Object>> calls=new TreeMap<>();long issued=EvaluationRandom.number(ledger.get("issued"));if(old!=null){issued=Math.max(issued,EvaluationRandom.number(old.get("issued")));for(Object v:Json.asArray(old.get("calls"))){Map<String,Object> row=Json.asObject(v);calls.put(EvaluationRandom.number(row.get("callIndex")),row);}}for(Object v:Json.asArray(ledger.get("calls"))){Map<String,Object> row=Json.asObject(v);calls.put(EvaluationRandom.number(row.get("callIndex")),row);}Map<String,Object> merged=Json.object("billable",Boolean.TRUE.equals(ledger.get("billable"))||old!=null&&!Boolean.FALSE.equals(old.get("billable")),"issued",issued,"calls",new ArrayList<>(calls.values()));if(store==null)volatileUsage.put(id,merged);else store.save(runKey(id)+":usage",merged);}}
 private String runKey(String id){return owner+":"+id;}
 private void saveRun(EvaluationRun run){Map<String,Object> checkpoint=run.checkpoint();if(store==null)volatileRuns.put(run.id(),checkpoint);else store.save(runKey(run.id()),checkpoint);Map<String,Object> batch=batches.get(activeBatch);if(batch!=null)for(Map<String,Object> row:rows(batch))if(row.get("id").equals(run.id()))row.putAll(run.report(false));}
 private Map<String,Object> loadRun(String id){Map<String,Object> row=store==null?volatileRuns.get(id):store.load(runKey(id));if(row==null)throw new IllegalStateException("CHECKPOINT_MISSING");return row;}
 private List<Object> indexBatches(){List<Object> out=new ArrayList<>();for(Map<String,Object> batch:batches.values()){
  Map<String,Object> ref=new LinkedHashMap<>(batch);ref.remove("comparison");List<Object> cases=new ArrayList<>();for(Map<String,Object> row:rows(batch))cases.add(Json.object("id",row.get("id"),"status",row.get("status")));ref.put("cases",cases);out.add(ref);
 }return out;}
 private void saveIndex(){if(store!=null)store.save(owner,Json.object("schemaVersion",1,"revision",revision,"purgeJson",Json.write(new ArrayList<>(pendingPurge)),"paidQuota",Json.object("day",paidDay,"cases",paidCases),"batchesJson",Json.write(indexBatches()),"receiptsJson",Json.write(new ArrayList<>(receipts.values()))));}
 private void freeze(){if(active!=null)active.cancel();active=null;activeBatch=null;storageError=true;}
 private static long bounded(Map<String,Object> map,String key,long min,long max){long n=EvaluationRandom.number(map.get(key));if(n<min||n>max)throw new IllegalArgumentException("INVALID_"+key.toUpperCase(Locale.ROOT));return n;}
 public void close(){if(active!=null){if(!active.terminal()&&"RUNNING".equals(active.status()))active.pause();saveRun(active);active=null;activeBatch=null;}for(Map<String,Object> batch:batches.values())if(Arrays.asList("RUNNING","QUEUED").contains(batch.get("status")))batch.put("status","PAUSED");saveIndex();}
}
